// textconv: a C++ port of askai/relay/textconv.py for the Plus Modem's built-in relay.
//
// The model's streamed Markdown (UTF-8) becomes plain text events, exactly as the Python relay
// makes them: T (text to append) and N (a line break), with T text converted to Mac Roman by
// toMac() when it is sent. Works on Unicode code points (std::u32string) so Python's str
// semantics carry over one to one. The Unicode data Python gets from unicodedata comes from
// macroman_tables.h, generated by modem/tools/gen_macroman.py.
//
// Checked against the Python original by modem/tests/test_textconv.py.
#pragma once
#include <stddef.h>
#include <string>
#include <vector>

namespace tc {

typedef std::u32string ustr;
struct Ev { char kind; ustr text; };   // kind 'T' = text to append, 'N' = line break (text empty)

class PlainStream {                    // port of textconv.PlainStream
public:
    PlainStream();
    void reset();
    // Streamed model text as UTF-8. A chunk may end inside a multi-byte sequence: those bytes are
    // held for the next call. Appends the events Python's feed() returns (already pack()ed, max_t 200).
    void feed(const char *utf8, size_t n, std::vector<Ev> &out);
    // Python's finish(). A UTF-8 sequence still held back is first fed as U+FFFD (as Python's
    // incremental decoder would at the end); finish() doesn't reset the stream: call reset() to reuse it.
    void finish(std::vector<Ev> &out);

private:
    std::string pend_;                 // an incomplete UTF-8 sequence from the last chunk
    ustr buf_;                         // text of the current line not yet processed
    bool decided_;                     // the current line's prefix has been emitted
    bool inCode_;                      // inside a fenced code block
    ustr fence_;
    bool inIcode_;                     // inside an inline `code` span (may span words)
    bool started_;                     // any text emitted yet (leading blank lines are dropped)
    int newlines_;                     // line breaks owed (emitted lazily: trailing ones are dropped)
    std::vector<Ev> out_;

    void feedText(const ustr &text);
    void flush(std::vector<Ev> &out);
    void text(ustr s);
    void newline();
    ustr inlineText(const ustr &s);
    ustr prose(const ustr &s) const;
    bool holdLine(const ustr &line) const;
    ustr prefix(const ustr &line) const;
    bool completeLine(const ustr &line);
    ustr release(const ustr &rest, bool final);
};

void pack(std::vector<Ev> &events, size_t maxT = 200);  // textconv.pack, in place
std::string toMac(const ustr &s);                       // textconv.to_mac: Unicode -> Mac Roman bytes
std::string utf8ToMac(const std::string &utf8);         // decode + toMac (convenience)
std::string macToUtf8(const std::string &mac);          // textconv.from_mac, as UTF-8 (CRLF/CR -> "\n")
ustr utf8Decode(const std::string &s);                  // invalid bytes -> U+FFFD (as Python's "replace")
std::string utf8Encode(const ustr &s);

}  // namespace tc
